);

CREATE TABLE jobs (
    id INTEGER PRIMARY KEY,
    client_id INTEGER NOT NULL REFERENCES clients(id),
    master_id INTEGER REFERENCES masters(id),
    device TEXT NOT NULL,
    problem TEXT,
    price INTEGER,
    status TEXT NOT NULL DEFAULT 'принят',
    created TEXT NOT NULL
